def leadCaptures_sp(json_file: dict):
    conn = None
    cursor = None
    try:
        conn = connection()
        cursor = conn.cursor()
        cursor.execute("EXEC [dbo].[sp_leadCaptures] @pjsonfile = %s", (json.dumps(json_file),))
        # Upsert SP returns ONE row, ONE column -- use fetchone()[0]
        row = cursor.fetchone()
        json_result_str = row[0] if row and row[0] else '{"message": "ok"}'
        json_result = json.loads(json_result_str)

        # Apply ADR-002: Inspect SP result for error field and return non-2xx status
        if isinstance(json_result, dict) and "error" in json_result:
            # The constraint "non-2xx status for a duplicate rejection." implies 400 Bad Request.
            return JSONResponse(content=json_result, status_code=400)

        return JSONResponse(content=json_result, status_code=200)
    except Exception as e:
