export interface LeadCapture {
  leadCaptureId: number;
  companyId?: number | null; // Nullable as per ADR-001 for public submissions, but internal ops use it.
  fullName: string;
  email: string;
  companyName?: string | null;
  phone?: string | null;
  jobTitle?: string | null;
  message?: string | null;
  leadSource: string;
  interestArea?: string | null;
  status: string;
  assignedTo?: number | null; // FK to employees, can be null
  privacyConsentAccepted: boolean;
  created_At: string;
  updated_at?: string | null;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

// Specific payload for public create endpoint, omitting internal/server-set fields
export interface CreateLeadCapturePayload {
  fullName: string;
  email: string;
  companyName?: string | null;
  phone?: string | null;
  jobTitle?: string | null;
  message?: string | null;
  leadSource: string;
  interestArea?: string | null;
  privacyConsentAccepted: boolean;
}

export interface UpdateLeadCapturePayload {
  fullName?: string;
  email?: string;
  companyName?: string | null;
  phone?: string | null;
  jobTitle?: string | null;
  message?: string | null;
  leadSource?: string;
  interestArea?: string | null;
  status?: string;
  assignedTo?: number | null;
  privacyConsentAccepted?: boolean;
}

// GET ALL — POST /all_leadCaptures
export async function getAllLeadCaptures(companyId: number): Promise<LeadCapture[]> {
  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "companyId": companyId }] }), // Internal filtering uses companyId
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

// GET ONE — POST /one_leadCaptures
export async function getOneLeadCapture(leadCaptureId: number, companyId: number): Promise<LeadCapture | null> {
  const res = await fetch(BASE_URL + "/one_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ leadCaptureId, companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures && data.leadCaptures.length > 0 ? data.leadCaptures[0] : null;
}

// CREATE — action: 1 (Public endpoint, no companyId from client, status/assignedTo set by server)
export async function createLeadCapture(payload: CreateLeadCapturePayload): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 1, ...payload }] }),
  });
  // Backend artifact inspects 'error' field and returns 400, so res.ok is sufficient
  if (!res.ok) {
    const errorData = await res.json();
    throw new Error(errorData.error || errorData.message || 'Error al crear lead');
  }
  return await res.json();
}

// UPDATE — action: 2 (Internal operation, requires companyId for multi-tenancy)
export async function updateLeadCapture(leadCaptureId: number, companyId: number, payload: UpdateLeadCapturePayload): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 2, leadCaptureId, companyId, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3 (Internal operation, requires companyId for multi-tenancy)
export async function deleteLeadCapture(leadCaptureId: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 3, leadCaptureId, companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}
