              {INTEREST_AREAS.map(a => <IonSelectOption key={a.value} value={a.value}>{a.label}</IonSelectOption>)}
            </IonSelect>
          </div>
        </div>

        <IonList className="leadcapture-list ion-margin-top">
          {leads.length === 0 && !loading && (
            <IonItem>
              <IonLabel>No hay leads para mostrar.</IonLabel>
            </IonItem>
          )}
          {leads.map(lead => (
            <IonItem key={lead.leadCaptureId} className="leadcapture-item">
              <div className="leadcapture-item-content">
                <IonLabel>
                  <h2>{lead.fullName}</h2>
                  <p>{lead.email}</p>
                  {lead.companyName && <IonNote>{lead.companyName}</IonNote>}
                  <div className="leadcapture-item-meta">
                    <IonBadge color={getStatusColor(lead.status)}>{LEAD_STATUSES.find(s => s.value === lead.status)?.label || lead.status}</IonBadge>
                    <IonChip>{LEAD_SOURCES.find(s => s.value === lead.leadSource)?.label || lead.leadSource}</IonChip>
                    {lead.assignedTo && <IonChip><IonIcon icon={personOutline} /> {MOCK_EMPLOYEES.find(e => e.employeeId === lead.assignedTo)?.fullName || 'Desconocido'}</IonChip>}
                  </div>
                  <IonNote className="ion-text-wrap">Creado: {toHermosillo(lead.created_At)}</IonNote>
                  {lead.updated_at && <IonNote className="ion-text-wrap">Actualizado: {toHermosillo(lead.updated_at)}</IonNote>}
                </IonLabel>

                {canManage && (
                  <div className="leadcapture-item-actions">
                    <IonButton fill="clear" color="medium" onClick={() => handleEditClick(lead)}>
                      <IonIcon icon={createOutline} />
                    </IonButton>
                    <IonButton fill="clear" color="danger" onClick={() => handleDeleteClick(lead)}>
                      <IonIcon icon={trashOutline} />
                    </IonButton>
                  </div>
                )}
              </div>
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll onIonInfinite={loadMoreItems} threshold="100px" disabled={!hasMore || loading}>
          <IonInfiniteScrollContent loadingSpinner="crescent" loadingText="Cargando más leads..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonToast
          isOpen={showToast}
          message={toastMessage}
          duration={3000}
          onDidDismiss={() => setShowToast(false)}
          color={toastMessage.toLowerCase().includes('error') ? 'danger' : 'success'}
        />

        {/* Create Lead Modal */}
        <IonModal isOpen={showCreateModal} onDidDismiss={() => setShowCreateModal(false)} className="leadcapture-modal">
          <Header
            presentAlertPopover={presentAlertPopover}
            presentMailPopover={presentMailPopover}
            screenTitle="Crear Nuevo Lead"
            onClose={() => setShowCreateModal(false)}
          />
          <IonContent className="ion-padding">
            <div className="wizard-form-fields">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre Completo *"
                  labelPlacement="floating"
                  value={createForm.fullName}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCreateForm(p => ({ ...p, fullName: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Email *"
                  labelPlacement="floating"
                  type="email"
                  value={createForm.email}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCreateForm(p => ({ ...p, email: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de la Empresa"
                  labelPlacement="floating"
                  value={createForm.companyName}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCreateForm(p => ({ ...p, companyName: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Teléfono"
                  labelPlacement="floating"
                  type="tel"
                  value={createForm.phone}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCreateForm(p => ({ ...p, phone: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Puesto"
                  labelPlacement="floating"
                  value={createForm.jobTitle}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCreateForm(p => ({ ...p, jobTitle: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonTextarea
                  fill="outline"
                  label="Mensaje"
                  labelPlacement="floating"
                  value={createForm.message}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCreateForm(p => ({ ...p, message: e.detail.value! }))}
                  rows={3}
                />
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Fuente del Lead *"
                  labelPlacement="floating"
                  value={createForm.leadSource}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setCreateForm(p => ({ ...p, leadSource: e.detail.value! }))}
                >
                  {LEAD_SOURCES.map(s => <IonSelectOption key={s.value} value={s.value}>{s.label}</IonSelectOption>)}
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Área de Interés"
                  labelPlacement="floating"
                  value={createForm.interestArea}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setCreateForm(p => ({ ...p, interestArea: e.detail.value! }))}
                >
                  {INTEREST_AREAS.map(a => <IonSelectOption key={a.value} value={a.value}>{a.label}</IonSelectOption>)}
                </IonSelect>
              </div>
              <div className="wizard-field-group">
                <IonToggle
                  checked={createForm.privacyConsentAccepted}
                  onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setCreateForm(p => ({ ...p, privacyConsentAccepted: e.detail.checked }))}
                  labelPlacement="end"
                >
                  Acepto la política de privacidad *
                </IonToggle>
              </div>
            </div>

            <IonButton expand="block" className="ion-margin-top" onClick={handleCreateSubmit} disabled={saving}>
              {saving ? <IonSpinner name="dots" /> : 'Crear Lead'}
            </IonButton>
          </IonContent>
        </IonModal>

        {/* Edit Lead Modal */}
        <IonModal isOpen={showEditModal} onDidDismiss={() => setShowEditModal(false)} className="leadcapture-modal">
          <Header
            presentAlertPopover={presentAlertPopover}
            presentMailPopover={presentMailPopover}
            screenTitle={`Editar Lead: ${selectedLead?.fullName}`}
            onClose={() => setShowEditModal(false)}
          />
          <IonContent className="ion-padding">
            {selectedLead && (
              <div className="wizard-form-fields">
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Nombre Completo"
                    labelPlacement="floating"
                    value={editForm.fullName}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditForm(p => ({ ...p, fullName: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Email"
                    labelPlacement="floating"
                    type="email"
                    value={editForm.email}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditForm(p => ({ ...p, email: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Nombre de la Empresa"
                    labelPlacement="floating"
                    value={editForm.companyName}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditForm(p => ({ ...p, companyName: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Teléfono"
                    labelPlacement="floating"
                    type="tel"
                    value={editForm.phone}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditForm(p => ({ ...p, phone: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Puesto"
                    labelPlacement="floating"
                    value={editForm.jobTitle}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditForm(p => ({ ...p, jobTitle: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonTextarea
                    fill="outline"
                    label="Mensaje"
                    labelPlacement="floating"
                    value={editForm.message}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditForm(p => ({ ...p, message: e.detail.value! }))}
                    rows={3}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonSelect
                    fill="outline"
                    label="Fuente del Lead"
                    labelPlacement="floating"
                    value={editForm.leadSource}
                    onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setEditForm(p => ({ ...p, leadSource: e.detail.value! }))}
                  >
                    {LEAD_SOURCES.map(s => <IonSelectOption key={s.value} value={s.value}>{s.label}</IonSelectOption>)}
                  </IonSelect>
                </div>
                <div className="wizard-field-group">
                  <IonSelect
                    fill="outline"
                    label="Área de Interés"
                    labelPlacement="floating"
                    value={editForm.interestArea}
                    onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setEditForm(p => ({ ...p, interestArea: e.detail.value! }))}
                  >
                    {INTEREST_AREAS.map(a => <IonSelectOption key={a.value} value={a.value}>{a.label}</IonSelectOption>)}
                  </IonSelect>
                </div>
                <div className="wizard-field-group">
                  <IonSelect
                    fill="outline"
                    label="Estado"
                    labelPlacement="floating"
                    value={editForm.status}
                    onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setEditForm(p => ({ ...p, status: e.detail.value! }))}
                  >
                    {LEAD_STATUSES.map(s => <IonSelectOption key={s.value} value={s.value}>{s.label}</IonSelectOption>)}
                  </IonSelect>
                </div>
                <div className="wizard-field-group">
                  <IonSelect
                    fill="outline"
                    label="Asignado A"
                    labelPlacement="floating"
                    value={editForm.assignedTo}
                    onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setEditForm(p => ({ ...p, assignedTo: e.detail.value! }))}
                  >
                    <IonSelectOption value={null}>Sin asignar</IonSelectOption>
                    {MOCK_EMPLOYEES.map(emp => <IonSelectOption key={emp.employeeId} value={emp.employeeId}>{emp.fullName}</IonSelectOption>)}
                  </IonSelect>
                </div>
                <div className="wizard-field-group">
                  <IonToggle
                    checked={editForm.privacyConsentAccepted}
                    onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setEditForm(p => ({ ...p, privacyConsentAccepted: e.detail.checked }))}
                    labelPlacement="end"
                  >
                    Acepta política de privacidad
                  </IonToggle>
                </div>
              </div>
            )}

            <IonButton expand="block" className="ion-margin-top" onClick={handleUpdateSubmit} disabled={saving}>
              {saving ? <IonSpinner name="dots" /> : 'Guardar Cambios'}
            </IonButton>
          </IonContent>
        </IonModal>

        {/* Delete Lead Alert */}
        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Estás seguro de que quieres eliminar el lead de ${selectedLead?.fullName}? Esta acción no se puede deshacer.`}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: handleDeleteConfirm, cssClass: 'danger' },
          ]}
        />

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={() => setShowCreateModal(true)}>
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>
      </IonContent>
    </IonPage>
  );
};

export default LeadCapturePage;
